response.text:
[
  {
    "description": "When the Legacy Payment API times out on a refund request, the payment worker retries without an idempotency key, causing a duplicate refund because the API always executes duplicate requests as separate side effects.",
    "rationale": "This experiment isolates the interaction between the worker's retry behavior (triggered by timeout) and the payment API's lack of idempotency. The 'timeout' intervention creates the ambiguous state that prompts a retry, while the 'missing_idempotency_key' intervention ensures the retry cannot be deduplicated by the API. Together they test whether the system violates the network-idempotency invariant under the exact failure mode described in the payment service contract (duplicate charge on retry, always). No other intervention combination directly produces this specific duplicate-refund scenario.",
    "expectedInvariant": "r04-network-idempotency",
    "interventions": ["timeout", "missing_idempotency_key"],
    "confidence": 0.9
  }
]

